const ELEMENT_PROP_KEYS = new Set(["softness","bloom","aberration","vignette","distortion","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  softness: 0.5,
  bloom: 0.5,
  aberration: 0.5,
  vignette: 0.5,
  distortion: 0.05,
  speed: 1,
};

type CameraLensElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CameraLensBase>;

const CameraLensInner = forwardRef<
  HTMLDivElement,
  CameraLensElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<CameraLens>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <CameraLensBase
          {...(componentProps as unknown as ComponentProps<typeof CameraLensBase>)}
        />
      </div>
    </Sequence>
  );
});

